/**
 * generate-bundle.js
 *
 * Reads the Vite-built dist/index.html (all JS + CSS inlined) and writes it
 * as a TypeScript string constant that TiptapEditor.tsx imports at compile time.
 *
 * Run automatically as part of `npm run build`:
 *   vite build && node generate-bundle.js
 */

const fs = require('fs')
const path = require('path')

const distHtml = fs.readFileSync(path.join(__dirname, 'dist', 'index.html'), 'utf-8')

// Escape for a TypeScript template literal
const escaped = distHtml.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${')

const output = `/**
 * tiptap-editor-bundle.ts  —  AUTO-GENERATED.  DO NOT EDIT.
 *
 * Generated by: cd editor-bundle && npm run build
 *
 * Contains the full Tiptap editor with all JS inlined — no CDN dependency.
 * Commit this file so the app works offline from fresh clone.
 */
export const TIPTAP_EDITOR_BUNDLE: string = \`${escaped}\`
`

const outPath = path.join(__dirname, '..', 'src', 'utils', 'tiptap-editor-bundle.ts')
fs.writeFileSync(outPath, output)
console.log('✓ Offline bundle written to', path.relative(process.cwd(), outPath))
